void initialize_plugin_on_io_thread(const std::string& mime_type) {
    // Retrieve plugin information for the specified MIME type
    PluginInfo* plugin_info = get_plugin_info_by_mime_type(mime_type);
    if (!plugin_info) {
        signal_event(EVENT_PLUGIN_NOT_FOUND);
        return;
    }

    // Ensure that the function runs on the IO thread
    if (!is_current_thread_io()) {
        schedule_on_io_thread(initialize_plugin_on_io_thread, mime_type);
        return;
    }

    // Retrieve plugin path and determine plugin type
    const char* plugin_path = plugin_info->get_path();
    bool is_pepper_plugin = is_pepper_plugin_type(plugin_path);

    // Open the appropriate communication channel
    if (is_pepper_plugin) {
        open_pepper_channel(plugin_path);
    } else {
        open_npapi_channel(plugin_path);
    }

    // Manage reference count until the channel is opened or an error occurs
    increment_ref_count(plugin_info);
}
